changes=json.loads('{"server/index.mjs": [["   if(p===\'/api/users/password\'){", "   if(p===\'/api/account/password\'){\\n    const a=await signedIn(req);if(a.user_id!==\'u0\')fail(403,\'Account owner only.\');if(req.method!==\'POST\')fail(405,\'Use POST.\');\\n    throttle(\'account-password:\'+a.user_id);const b=await payload(req);\\n    if(typeof b.password!==\'string\'||b.password.length<14||b.password.length>200)fail(422,\'Choose a password of 14 to 200 characters.\');\\n    return await transactionJSON(res,200,async q=>{\\n     const u=(await q(\'SELECT password_hash,totp_secret FROM users WHERE id=$1\',[a.user_id]))[0];\\n     if(!u?.totp_secret||typeof b.code!==\'string\'||!/^\\\\d{6}$/.test(b.code)||!totpOK(unseal(u.totp_secret,key).toString(),b.code))fail(422,\'Enter the current six-digit code from your authenticator app.\');\\n     if(!passwordOK(b.password,u.password_hash))await q(\'UPDATE users SET password_hash=$1 WHERE id=$2\',[passwordHash(b.password),a.user_id]);\\n     await q(\'DELETE FROM sessions WHERE user_id=$1 AND token_hash<>$2\',[a.user_id,a.token_hash]);\\n     await audit(q,a.user_id,\'account.password_changed\',a.user_id);return {ok:true};\\n    });\\n   }\\n   if(p===\'/api/users/password\'){"]], "site/app.js": [["V.more=function(){", "V.password=function(){if(!REMOTE||S().me!==\'u0\')return V.more();return `<section class=\\"card\\"><a href=\\"#/more\\">\\u2190 Back</a><h2>Change my password</h2><p>Choose a new password for steven@tharongroup.com. You stay signed in on this phone; other devices will need the new password. Your authenticator remains enabled.</p><form data-form=\\"ownPassword\\"><label>New password<input class=\\"input\\" name=\\"password\\" type=\\"password\\" autocomplete=\\"new-password\\" minlength=\\"14\\" maxlength=\\"200\\" required></label><label>Confirm new password<input class=\\"input\\" name=\\"confirm\\" type=\\"password\\" autocomplete=\\"new-password\\" minlength=\\"14\\" maxlength=\\"200\\" required></label><label>Authenticator code<input class=\\"input\\" name=\\"code\\" type=\\"text\\" inputmode=\\"numeric\\" autocomplete=\\"one-time-code\\" pattern=\\"[0-9]{6}\\" minlength=\\"6\\" maxlength=\\"6\\" required></label><p class=\\"small muted\\">Use the current six-digit code for Tharon Leads from your authenticator app.</p><p class=\\"small\\" role=\\"status\\" data-password-status></p><button class=\\"btn primary\\" type=\\"submit\\">Save new password</button></form></section>`;};\\n\\nV.more=function(){"], ["return `<section class=\\"card menu\\">${items.map", "if(REMOTE&&S().me===\'u0\')items.push([\'password\',\'Change my password\',\'Choose a new password using your authenticator\']);\\nreturn `<section class=\\"card menu\\">${items.map"], ["more:\'More\',team:\'Team\'", "more:\'More\',password:\'Change my password\',team:\'Team\'"], ["  if(k===\'staffPassword\'){", "  if(k===\'ownPassword\'){\\n    const status=f.querySelector(\'[data-password-status]\');\\n    if(f.elements.password.value!==f.elements.confirm.value){status.textContent=\'Passwords do not match.\';return;}\\n    const button=f.querySelector(\'button[type=\\"submit\\"]\');button.disabled=true;status.textContent=\'Saving\\u2026\';\\n    try{await TL.flush();await TLRemote.request(\'/api/account/password\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({password:f.elements.password.value,code:f.elements.code.value.trim()})});f.reset();status.textContent=\'Password saved. Use your new password and authenticator code to sign in on your computer.\';toast(\'Your password is saved.\');}catch(err){status.textContent=err.message+\' Your password change is not confirmed. Keep this page open and retry with a current authenticator code.\';}finally{button.disabled=false;}return;\\n  }\\n  if(k===\'staffPassword\'){"]]}')
for name,replacements in changes.items():
 p=r/name;s=p.read_text()
 for old,new in replacements:
  if s.count(old)!=1: raise SystemExit('Unexpected source for password update: '+name)
  s=s.replace(old,new,1)
 p.write_text(s)

