(r/'test/account-password.test.mjs').write_text('import test from \'node:test\';\nimport assert from \'node:assert/strict\';\nimport {mkdtempSync,rmSync,readFileSync} from \'node:fs\';\nimport {tmpdir} from \'node:os\';\nimport path from \'node:path\';\nimport {randomUUID,createHmac} from \'node:crypto\';\nimport {createApplication} from \'../server/index.mjs\';\nimport {openStore} from \'../server/store.mjs\';\nimport {totpCode,passwordOK} from \'../server/security.mjs\';\n\ntest(\'owner password change requires session, CSRF and TOTP; commits atomically; preserves current session; safe retry\',async()=>{\n const dir=mkdtempSync(path.join(tmpdir(),\'tharon-password-\')),setup=randomUUID(),secret=\'synthetic-session-secret\',password=\'synthetic-old-password-123\',next=\'synthetic-new-password-456\';\n let failCommit=false;const store=await openStore(\'\',path.join(dir,\'db\'),{beforeCommit:()=>{if(failCommit){failCommit=false;throw Error(\'injected commit failure\');}}});\n const app=await createApplication({store,schedule:false,env:{NODE_ENV:\'test\',APP_MODE:\'live\',PHI_APPROVED:\'true\',DATABASE_URL:\'\',APP_ORIGIN:\'\',ADMIN_SETUP_TOKEN:setup,SESSION_SECRET:secret}});\n await new Promise(r=>app.server.listen(0,\'127.0.0.1\',r));const origin=\'http://127.0.0.1:\'+app.server.address().port;\n async function call(p,{method=\'GET\',data,cookie,csrf,headers={}}={}){const r=await fetch(origin+p,{method,redirect:\'manual\',headers:{Origin:origin,...(data?{\'Content-Type\':\'application/json\'}:{}),...(cookie?{Cookie:cookie}:{}),...(csrf?{\'X-CSRF-Token\':csrf}:{}),...headers},body:data?JSON.stringify(data):undefined});return {status:r.status,body:await r.json(),cookie:r.headers.get(\'set-cookie\')?.split(\';\')[0]};}\n try{\n const info=await call(\'/auth/setup\',{method:\'POST\',data:{token:setup}}),code=()=>totpCode(info.body.totpSecret);\n assert.equal((await call(\'/auth/activate\',{method:\'POST\',data:{token:setup,password,code:code()}})).status,200);\n const login=async pw=>call(\'/auth/login\',{method:\'POST\',data:{email:\'steven@tharongroup.com\',password:pw,code:code()}});\n const first=await login(password),second=await login(password),boot=await call(\'/api/state\',{cookie:first.cookie});const auth={cookie:first.cookie,csrf:boot.body.csrf};\n const change=(data,extra={})=>call(\'/api/account/password\',{method:\'POST\',...auth,data,...extra});\n assert.equal((await call(\'/api/account/password\',{method:\'POST\',data:{password:next,code:code()}})).status,401);\n assert.equal((await change({password:next,code:code()},{csrf:\'wrong\'})).status,403);\n assert.equal((await change({password:next,code:code()},{headers:{Origin:\'https://invalid.example\'}})).status,403);\n assert.equal((await change({password:\'short\',code:code()})).status,422);\n assert.equal((await change({password:next,code:\'invalid\'})).status,422);\n assert.equal((await change({password:next})).status,422);\n for(const userId of [\'u1\',\'u4\',\'u5\']){const token=\'synthetic-\'+userId;await store.query(\'INSERT INTO sessions (token_hash,user_id,expires_at,csrf) VALUES ($1,$2,$3,$4)\',[createHmac(\'sha256\',secret).update(token).digest(\'hex\'),userId,Date.now()+60000,\'test-csrf\']);assert.ok([401,403].includes((await change({password:next,code:code()},{cookie:\'tl_session=\'+token,csrf:\'test-csrf\'})).status));}\n failCommit=true;assert.equal((await change({password:next,code:code()})).status,500);\n assert.ok(passwordOK(password,(await store.query(\'SELECT password_hash FROM users WHERE id=$1\',[\'u0\']))[0].password_hash));\n assert.equal((await call(\'/api/state\',{cookie:second.cookie})).status,200);\n assert.equal((await store.query(\'SELECT * FROM audit_log WHERE action=$1\',[\'account.password_changed\'])).length,0);\n // Ignore a successful response, then retry exactly the same proposed password.\n await change({password:next,code:code()});\n assert.equal((await change({password:next,code:code()})).status,200);\n assert.equal((await call(\'/api/state\',{cookie:first.cookie})).status,200);\n assert.equal((await call(\'/api/state\',{cookie:second.cookie})).status,401);\n assert.equal((await login(password)).status,401);assert.equal((await login(next)).status,200);\n const audit=JSON.stringify(await store.query(\'SELECT * FROM audit_log\'));assert.ok(!audit.includes(next));assert.ok(!audit.includes(password));assert.ok(!audit.includes(info.body.totpSecret));\n }finally{await app.close();rmSync(dir,{recursive:true,force:true});}\n});\ntest(\'password view is owner-only and only clears fields after success\',()=>{const s=readFileSync(new URL(\'../site/app.js\',import.meta.url),\'utf8\');assert.match(s,/V.password=function\\(\\)\\{if\\(!REMOTE\\|\\|S\\(\\).me!==\'u0\'\\)/);assert.match(s,/data-password-status/);assert.match(s,/maxlength="6"/);assert.ok(s.indexOf("await TLRemote.request(\'/api/account/password\'")<s.indexOf(\'f.reset();status.textContent=\'));});\n')
